package com.campusos.backend.service;
import com.campusos.backend.entity.Subject; import com.campusos.backend.entity.Teacher; import com.campusos.backend.entity.User; import com.campusos.backend.enums.Role; import com.campusos.backend.repository.SubjectRepository; import com.campusos.backend.repository.TeacherRepository; import com.campusos.backend.repository.UserRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class SubjectService { private final SubjectRepository repo; private final UserRepository users; private final TeacherRepository teachers; public SubjectService(SubjectRepository repo,UserRepository users,TeacherRepository teachers){this.repo=repo;this.users=users;this.teachers=teachers;} public Subject createSubject(Subject s,String email){User u=users.findByEmail(email).orElseThrow();Teacher h=teachers.findByUser(u).orElseThrow();if(!Boolean.TRUE.equals(h.getHod())||h.getDepartment()==null||s.getDepartment()==null||!h.getDepartment().getId().equals(s.getDepartment().getId()))throw new RuntimeException("HOD can manage subjects only in their own department");return repo.save(s);} public List<Subject> getAllSubjects(){return repo.findAll();} public Subject updateSubject(Long id,Subject input,String email){Subject s=repo.findById(id).orElseThrow(()->new RuntimeException("Subject not found"));User u=users.findByEmail(email).orElseThrow();Teacher h=teachers.findByUser(u).orElseThrow();if(!Boolean.TRUE.equals(h.getHod())||s.getDepartment()==null||h.getDepartment()==null||!h.getDepartment().getId().equals(s.getDepartment().getId()))throw new RuntimeException("HOD can manage subjects only in their own department"); s.setName(input.getName());s.setCode(input.getCode());s.setSemester(input.getSemester());s.setAcademicYear(input.getAcademicYear()); return repo.save(s);} public void deleteSubject(Long id,String email){Subject s=repo.findById(id).orElseThrow(()->new RuntimeException("Subject not found"));User u=users.findByEmail(email).orElseThrow();Teacher h=teachers.findByUser(u).orElseThrow();if(!Boolean.TRUE.equals(h.getHod())||h.getDepartment()==null||s.getDepartment()==null||!h.getDepartment().getId().equals(s.getDepartment().getId()))throw new RuntimeException("Only the HOD can manage subjects in their own department");repo.deleteById(id);} }
